"""Freeze the bounded T081-T090 scientific review and its reproducible receipts."""
import csv, hashlib, json
from pathlib import Path

B=Path(__file__).resolve().parent
Q=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf-8')))
T={x['sample_id']:x for x in json.loads((B/'lead-timing.json').read_text())}

# Editorial decisions are evidence based; the numeric fits alone do not set verdicts.
V={
'T081':dict(verdict='PROBABLE',novelty='UNKNOWN',period=True,depth=290.0,
 finding='Five coherent same-kind deep raw eclipses in sectors 6, 33 and 87 have a 10.5182414-day clock (cycles 0, 1, 70, 71, 209; max selected fit residual 0.0003 d). Other flagged events sit at a distinct phase. The stronger local event is about 290 ppt, and the independent TESSCut aperture shows a target-region deficit. The Gaia SB2 orbit is 40.00793 +/- 0.00942 d, not this clock or a supported integer harmonic.',
 limits='The event source is localized to the target region, but an unresolved companion inside the TESS aperture remains possible. A separate short-period EB or hierarchical system is by-catch; no Gaia-orbit eclipse is established. Conditional timing error omits selection and pipeline systematics.',
 next='Deblend the target and nearby unresolved light, obtain a second pipeline time series, and determine whether the short-period EB belongs to the Gaia SB2 system.'),
'T082':dict(verdict='PROBABLE',novelty='UNKNOWN',period=True,depth=413.0,
 finding='Nine same-kind raw eclipses from sectors 10, 37, 38, 64, 100 and 101 fit 16.2039887 d (cycles 0, 1, 46-48, 91, 155-157; max residual 0.0016 d). Deep opposite-kind events are interleaved. The target-region TESSCut deficit is real. Three times the eclipse period is 48.61197 d, 0.25948 d below the Gaia SB2 period 48.87145 +/- 0.00975 d, so a simple third-harmonic identity fails.',
 limits='The local pixel check does not exclude an unresolved source or establish a physical link to the Gaia SB2. The Gaia-period association fails even though the short-period eclipse train is real. Conditional timing error omits model and reduction systematics.',
 next='Fit separate eclipse kinds in an independent pipeline and obtain source-resolved photometry or spectroscopy to identify the 16.204-day binary.'),
'T083':dict(verdict='PROBABLE',novelty='UNKNOWN',period=True,depth=313.1,
 finding='Sector 89 contains a 313 ppt A eclipse at BTJD 3735.576 and two B eclipses at 3721.493 and 3746.148; the B spacing is 24.6552 d, near the Gaia SB1 24.6796 d. Explicit two-to-five-cycle shorter aliases predict intermediate B eclipses in fully covered s89 core windows, but none approaches the observed 50-55 ppt B depth. Prior vet23 measured all three in QLP and TARS, localized them on target pixels, and found no corresponding deep eclipse at covered earlier s8, s9 and s62 conjunctions. The present TESSCut difference peak is also on target. Gaia has a second 300.8-day astrometric solution, so evolving eclipse geometry is plausible but unproved.',
 limits='The real on-target eclipses repeat within sector 89, yet the same ephemeris failed in earlier covered sectors. A persistent Gaia-orbit eclipse geometry or precession explanation is unproved, leaving a failed stability check and a probable verdict. Prior local investigation is not a published exact-target eclipse match; four current catalogue gates remain unknown. TESS s110/s111 are planned rather than available in the present footprint query.',
 next='Measure the next available sector 110/111 eclipses and compare depth and timing with the sector 89 events; obtain radial velocities of the proposed outer body.'),
'T084':dict(verdict='PLAUSIBLE',novelty='UNKNOWN',period=False,depth=107.0,
 finding='Raw eclipse-shaped deficits near BTJD 2521.286 (s44) and 3243.049 (s71) are separated by 721.763 d; 22 Gaia-near cycles give a conditional 32.807395 d period. The s71 event is about 107 ppt in the raw fit and 70 ppt in the independent TESSCut aperture. The target is saturated, so the split bleed-pattern difference image does not locate a unique peak. Explicit 20-24-cycle aliases were checked against s72: the Gaia-near 22-cycle next window at 3275.856 has zero core cadences, while 20- and 21-cycle predictions are fully covered and flat. The 23- and 24-cycle predictions also fall in gaps.',
 limits='Only two secure same-kind centers exist; the principal Gaia-near alias and two shorter aliases remain untested by actual coverage. Saturation limits pixel attribution. The footprint lists an unusual s1751 record without a usable cached light curve; it is not counted as a confirming sector.',
 next='Obtain a fully covered same-kind repeat and saturation-aware difference image, then resolve the integer-cycle alias.'),
'T085':dict(verdict='REFUTED',novelty='UNKNOWN',period=False,depth=None,
 finding='The QLP raw light curve contains a strong 4.23712-day double-eclipse train, including the sector-7 1492.016 dip. This is not a target eclipse: the prior dedicated vet122980411 investigation stacked both kinds across three sectors and found deficit centroids 0.5-0.7 TESS pixels east of the target, within 0.2-0.35 pixels of HJ 68 B. Single-source fits favored that 17-arcsec neighbor by delta chi-square 1,300-48,600. Deblended TGLC s7 primary depths were 3.6% at the queued target versus 40.7% and 51.9% for the two Gaia components of B. The present independent TESSCut signed difference moment also points toward B.',
 limits='The neighboring EB is real; this verdict refutes its assignment to the queued Gaia SB1 target, whose distinct 51.025-day spectroscopic orbit is not disproved. The present single-event moment alone would be insufficient; prior stacked PSF/deblended evidence decides attribution.',
 next='If revisiting the 51.025-day Gaia target orbit, search for a separate target-centered eclipse after modeling HJ 68 B contamination.'),
'T086':dict(verdict='CONFIRMED',novelty='KNOWN',period=True,depth=61.0,
 finding='Four clean same-kind raw eclipses in sectors 13, 39, 67 and 93 fit 58.731513 d at cycles 0, 12, 25 and 37, with max timing residual below 0.001 d; this agrees with Gaia 58.732564 +/- 0.007279 d. Actual P/2 alternative windows in s12 and s101 are well covered and flat. A second TESSCut extraction has a target-centered 59 ppt deficit with valid background. Gaia Thiele-Innes inversion gives inclination 90.47 deg and argument of periastron about 30.33 deg; the observed epoch is 0.064 d from predicted conjunction with 0.177-d source-specific linear full-covariance uncertainty (0.36 sigma). Public Chopard v1.2.0 independently records this exact Gaia source and TIC as an eclipser in four of seven conjunction windows, with QLP and TESS-SPOC agreement and an orbit-consistency flag.',
 limits='The source is previously identified, so it is a known recovery and cannot enter a new-system count. Gaia conjunction covariance is linearly propagated from the full 15-parameter fit; nonlinear tails and orbital model systematics are not calibrated. The public dossier quotes 2.034% depth, different from the roughly 4.6-6% raw/custom-aperture depth here; the reduction or event-definition cause is untested. The fitted timing uncertainty is conditional.',
 next='Cite the public Chopard v1.2.0 dossier if discussing this known recovery; refine its ephemeris with a full independent reduction if needed.'),
'T087':dict(verdict='CONFIRMED',novelty='UNKNOWN',period=True,depth=133.0,
 finding='Four same-kind raw eclipses at BTJD 2135.654, 2162.187, 3939.892 and 3966.425 occur at cycles 0, 1, 68 and 69, giving 26.532911 d with a maximum selected residual below 0.001 d. The adjacent pairs fix the cycle spacing; well-covered P/2 windows in s31 and s97 are flat. Gaia has 26.536860 +/- 0.003424 d, consistent at about 1.2 sigma. The TESSCut aperture repeats a target-region eclipse deficit with valid positive target flux and no nominal capable Gaia neighbor. Gaia AstroSpectroSB1 Thiele-Innes A/B/F/G recover inclination 91.89 deg and argument of periastron 39.76 deg, checked against C/H. The observed epoch is 0.193 d before the edge-on conjunction prediction, with 0.197-d source-specific linear full-covariance uncertainty (0.98 sigma).',
 limits='The Gaia conjunction covariance is linearly propagated from the full 15-parameter fit; nonlinear tails and orbital model systematics are not calibrated. The custom aperture is the same TESS photons, not another observing occasion. A formal timing error is conditional.',
 next='Remeasure the eclipses in another time-series pipeline and complete the unavailable catalogue gates before any novelty claim.'),
'T088':dict(verdict='PLAUSIBLE',novelty='UNKNOWN',period=False,depth=235.5,
 finding='A deep raw s50 eclipse-shaped event near BTJD 2670.511 and a shallower s77 event near 3422.485 are real in two different observing occasions; independent TESSCut extractions show about 219 and 30 ppt in target-region apertures. Their separation and Gaia phases do not form a demonstrated same-kind 31.75594-day clock. A 12.16-arcsec Gaia neighbor with approximate G flux ratio 0.04 could supply the s77 blended depth.',
 limits='The two events have very different depths, are at different Gaia phases and are not securely attributed to one source or eclipse kind. There is no measured repeating period. The Gaia-neighbor flux ratio is only an approximate screening bound.',
 next='Use source-resolving difference/PSF photometry for both events and obtain another same-kind eclipse before testing cycle aliases.'),
'T089':dict(verdict='CONFIRMED',novelty='UNKNOWN',period=True,depth=39.2,
 finding='Six same-kind raw events in sectors 13, 27, 67, 94, 101 and 103 fit 29.749050 d over cycles 0, 13, 50, 74, 82 and 84 (largest residual 0.002 d). Covered P/2 alternate windows in s13, s67, s94 and s101 are flat, including fully covered s67. This agrees with Gaia SB1 29.749180 +/- 0.006943 d. The selected s13 event is about 39 ppt in QLP raw SAP and 40 ppt in the independent valid TESSCut aperture, with a target-region difference deficit and no nominal capable Gaia neighbor. Gaia-covariance propagation places the measured epoch 0.092 d from a predicted conjunction with sigma 0.329 d.',
 limits='The current TESSCut aperture reuses TESS photons; its depth is not an independent observation. The local TESSCut check covers one representative event, and the period error is conditional on selected cycles and trapezoid fits. Four VizieR novelty gates remain unavailable.',
 next='Acquire an independent pipeline time series and complete the unavailable catalogue gates before any novelty claim.'),
'T090':dict(verdict='PROBABLE',novelty='UNKNOWN',period=True,depth=175.0,
 finding='A dense raw eclipse train across sectors 20, 47, 60, 73 and 74 has 18 selected same-kind centers fitting about 3.208895 d (cycles 0-462; largest residual 0.021 d, dominated by coarse/variable profiles). Another eclipse kind is interleaved. The independent TESSCut aperture sees a target-region 139 ppt dip. Gaia SB2 period 23.932237 +/- 0.001717 d is not an integer multiple of the short eclipse clock.',
 limits='The short-period binary may be an unresolved component or a separate system within the aperture. The precise physical connection to the Gaia SB2 is unproved; the formal fit error understates profile and pipeline systematics.',
 next='Deblend the aperture and compare separate eclipse kinds in an independent pipeline and spectroscopy to identify the 3.209-day system.'),
}

fields='sample_id,tic,sample_stratum,physical_verdict,full_review_completion,novelty_status,period_days,period_error_days,primary_epoch_btjd,depth_ppt,limitations,next_check,report'.split(',')
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as fh:
 w=csv.DictWriter(fh,fieldnames=fields);w.writeheader()
 for q in Q:
  sid=q['sample_id'];tic=q['tic'];v=V[sid];tim=T[sid];n=json.loads((B/tic/'lead-numeric.json').read_text())
  packet=B.parent/'source-packets'/tic/'sources.json'
  bulk=Path('[local-path-redacted]')/(tic+'.json')
  period=round(tim['period_days'],4 if sid=='T090' else 6) if v['period'] else None
  perr=tim.get('conditional_formal_period_error_days') if period else None
  fit_epoch=tim.get('epoch_btjd') if period else None
  epoch=tim.get('epoch_btjd') if period and sid in ('T086','T087','T089') else None
  if sid=='T090':perr=None # Profile scatter makes the formal value misleading.
  period_text=(f'{period:.4f}' if sid=='T090' else f'{period:.6f}') if period else ''
  rec=dict(sample_id=sid,tic=tic,sample_stratum=q['sample_stratum'],physical_verdict=v['verdict'],full_review_completion='COMPLETE',novelty_status=v['novelty'],period_days=period,period_error_days=perr,primary_epoch_btjd=epoch,depth_ppt=v['depth'],limitations=v['limits'],next_check=v['next'],report=str(B/tic/'REPORT.md'))
  w.writerow(rec)
  section=[f'# {sid} / TIC {tic}: {v["verdict"]}', '', f'Queue stratum: {q["sample_stratum"]}. Bounded physical review: complete. Catalogue novelty: {v["novelty"]}.', '', '## Deciding evidence', '',v['finding'],'', '## Measurement and scope', '',f'Gaia source {q["gaia_dr3"]}; selection orbit {q["gaia_period_days"]} d; Gaia G {q["gaia_G"]}. The raw QLP SAP analysis inspected {len(n["sources"])} hash-verified FITS sectors and {len(n["events"])} retained dip windows, including actual quality and time coverage. Local trapezoid centers, event depths, sectors, and source hashes are in [lead-numeric.json](lead-numeric.json); representative profiles are in lead-raw-*.png. These retained detector windows were not taken as verdicts.',f'Source packet SHA-256: {hashlib.sha256(packet.read_bytes()).hexdigest()}. Bulk-result SHA-256: {hashlib.sha256(bulk.read_bytes()).hexdigest()}.','']
  if period:
   section += [f'Selected same-kind fit: P = {period_text} d; T0 = {fit_epoch:.6f} BTJD; conditional formal period error = {perr:.7g} d.' if perr else f'Selected same-kind fit: P approximately {period_text} d; T0 = {fit_epoch:.6f} BTJD; formal period error not reported because profile scatter/systematics dominate.', 'Cycle numbers, chosen eclipse kind and residuals: [lead-timing.json](../lead-timing.json).', '']
  else: section += ['No supported unique same-kind eclipse period is reported for this queued target.','']
  section += ['The helper independently extracted the strongest event from TESSCut with a positive-flux target aperture and checked the difference pixels; see [helper audit](../helper-audit.md), [numeric pixel audit](../helper-pixel-audit.json), and helper-difference.png. It is a second reduction of the same TESS photons.','']
  if sid=='T085':
   prior=Path('[local-path-redacted] 5.1/made/appointments/vet122980411/progress.md')
   section += [f'Prior decisive source receipt: {prior}; SHA-256 {hashlib.sha256(prior.read_bytes()).hexdigest()}. Its pipeline comparisons and stacked difference-image PSF test supersede the single current cutout.','']
  if sid=='T083':
   prior=Path('[local-path-redacted] 5.1/made/appointments/vet23/REPORT.md')
   section += [f'Prior target-specific receipt: {prior}, section 4; SHA-256 {hashlib.sha256(prior.read_bytes()).hexdigest()}. The older data and precession hypothesis are reused as documented. Explicit within-sector alias checks: [lead-alias-t083.json](../lead-alias-t083.json).','']
  if sid=='T086':
   prior=B.parent/'shared-catalogues/chopard-overlaps.json'
   section += [f'Public exact-ID receipt: [shared Chopard overlap](../../shared-catalogues/chopard-overlaps.json), SHA-256 {hashlib.sha256(prior.read_bytes()).hexdigest()}, Gaia DR3 6360777231720947328, vetting/dossier.csv. This establishes KNOWN even though four other catalogue gates failed.','']
  if sid=='T084':section += ['Explicit alias/coverage calculations: [lead-alias-t084.json](../lead-alias-t084.json). The zero-cadence predicted window is a gap, not a null. Gaia point geometry from [Thiele-Innes inversion](../lead-thiele.json) also supports a conjunction, but does not resolve the timing alias.','']
  if sid in ('T086','T087','T089'):section += ['Actual half-period opposite-kind coverage: [lead-half-alias.json](../lead-half-alias.json).','']
  if sid in ('T086','T087'):section += ['Gaia orientation and point conjunction from [Thiele-Innes inversion](../lead-thiele.json); C/H cross-checks the angular branch. Source-specific full NSS covariance propagation: [lead-thiele-covariance.json](../lead-thiele-covariance.json).','']
  section += ['## Limits and next check','',v['limits'],'',v['next'],'','Catalogue status uses the [shared queue-wide audit](../../shared-catalogues/REPORT.md). Its four unavailable VizieR gates are unknown, not negative matches.','']
  (B/tic/'REPORT.md').write_text('\n'.join(section),encoding='utf-8')

(B/'lead-audit.md').write_text('''# Batch09 lead audit\n\nThe ten queue identities T081-T090 were retained exactly. I inspected representative raw SAP profiles and numeric timing for every target, checked FITS SHA-256 against the source packets, compared Gaia orbital periods and available covariance, and read the prior target-specific reports before deciding novelty or attribution. The helper independently extracted all ten selected windows from TESSCut, checked positive target flux/background, pixel differences, and a second T088 occasion. Their report and source receipts are retained here.\n\nT081, T082 and T090 have real repeated short-period eclipses, but their clocks fail association with the selecting Gaia SB2 orbit. They are probable by-catch, not refutations of the eclipse signals. T085 is a real neighbor EB positively assigned to HJ 68 B by a previous stacked PSF/deblending review and is refuted only as an eclipse of the queued target. T083 has real on-target repeated B eclipses, with shorter within-sector aliases tested, but older sectors fail the same ephemeris; it remains probable rather than confirmed. T084 has two plausible events and an explicit alias check; the Gaia-near s72 prediction is gapped. T088 has two dissimilar events without a same-kind clock or unique source. T086 is an exact-ID known Chopard eclipse recovery. T087 has compatible Gaia geometry recovered from Thiele-Innes coefficients and passes the bounded half-period check; it is physically confirmed with catalogue novelty unknown. T089 satisfies representative repeated raw, timing, target pixel, alternative extraction and Gaia-covariance conjunction checks, and its half-period alternative has covered flat windows; it is physically confirmed with catalogue novelty unknown.\n\nThe actual half-period coverage calculation is in lead-half-alias.json. The AstroSpectroSB1 orientation inversion and C/H branch check are in lead-thiele.json. Conditional formal timing errors in lead-timing.json are not calibrated uncertainties on all systematics. No universal period-sigma cut was applied. The current footprint check was bounded; a footprint listing alone is not an analyzed light curve. This batch did not alter the paper, ledger or other batches.\n''',encoding='utf-8')

with (B/'lead-audit.md').open('a',encoding='utf-8') as fh:
 fh.write('\nFull source-specific Gaia NSS covariance propagation for T086 and T087 is in lead-thiele-covariance.json. Their conjunction offsets are +0.064 +/- 0.177 d and -0.193 +/- 0.197 d (0.36 and 0.98 sigma), respectively. The 15-parameter ordering and column-major corr_vec interpretation follow Gaia DR3 documentation.\n')

manifest={}
for p in sorted(B.rglob('*')):
 if not p.is_file() or p.name in ('SHA256SUMS.json','ROOT-ACCEPTANCE.json') or '__pycache__' in p.parts:continue
 manifest[str(p.relative_to(B)).replace('\\','/')]=hashlib.sha256(p.read_bytes()).hexdigest()
(B/'SHA256SUMS.json').write_text(json.dumps({'algorithm':'sha256','files':manifest},indent=2)+'\n',encoding='utf-8')
print('wrote',len(Q),'reports and',len(manifest),'manifest entries')
